static void applyRleStream(uint16_t* dst, const uint8_t* rle, size_t rle_len) {
  size_t pos = 0;
  const size_t max_px = 704U * 440U;
  for (size_t i = 0; i + 2 < rle_len && pos < max_px; i += 3) {
    uint8_t cnt = rle[i];
    uint16_t col = static_cast<uint16_t>(rle[i + 1]) | (static_cast<uint16_t>(rle[i + 2]) << 8);
    if (col == 0U) {
      pos += cnt;
    } else {
      for (uint8_t k = 0; k < cnt && pos < max_px; ++k) {
        dst[pos++] = col;
      }
    }
  }
}

bool decodeStage3DFrame(const char* key, uint16_t* dst_rgb565) {
  if (!key || !dst_rgb565) return false;
  if (strcmp(key, "night") == 0) {
    applyRleStream(dst_rgb565, kStageRle_night, sizeof(kStageRle_night));
    return true;
  }
  applyRleStream(dst_rgb565, kStageRle_clear, sizeof(kStageRle_clear));
  if (strcmp(key, "clear") == 0) return true;
  if (strcmp(key, "partly") == 0) {
    applyRleStream(dst_rgb565, kStageRle_partly, sizeof(kStageRle_partly));
    return true;
  }
  if (strcmp(key, "sunrise") == 0) {
    applyRleStream(dst_rgb565, kStageRle_sunrise, sizeof(kStageRle_sunrise));
    return true;
  }
  if (strcmp(key, "sunset") == 0) {
    applyRleStream(dst_rgb565, kStageRle_sunset, sizeof(kStageRle_sunset));
    return true;
  }
  if (strncmp(key, "wind", 4) == 0) {
    applyRleStream(dst_rgb565, kStageRle_wind, sizeof(kStageRle_wind));
    if (strcmp(key, "wind_1") == 0) applyRleStream(dst_rgb565, kStageRle_wind_1, sizeof(kStageRle_wind_1));
    else if (strcmp(key, "wind_2") == 0) applyRleStream(dst_rgb565, kStageRle_wind_2, sizeof(kStageRle_wind_2));
    return true;
  }
  applyRleStream(dst_rgb565, kStageRle_overcast, sizeof(kStageRle_overcast));
  if (strcmp(key, "overcast") == 0) return true;
  if (strncmp(key, "rain", 4) == 0) {
    applyRleStream(dst_rgb565, kStageRle_rain, sizeof(kStageRle_rain));
    if (strcmp(key, "rain_1") == 0) applyRleStream(dst_rgb565, kStageRle_rain_1, sizeof(kStageRle_rain_1));
    else if (strcmp(key, "rain_2") == 0) applyRleStream(dst_rgb565, kStageRle_rain_2, sizeof(kStageRle_rain_2));
    return true;
  }
  if (strncmp(key, "storm", 5) == 0) {
    applyRleStream(dst_rgb565, kStageRle_storm, sizeof(kStageRle_storm));
    if (strcmp(key, "storm_1") == 0) applyRleStream(dst_rgb565, kStageRle_storm_1, sizeof(kStageRle_storm_1));
    else if (strcmp(key, "storm_2") == 0) applyRleStream(dst_rgb565, kStageRle_storm_2, sizeof(kStageRle_storm_2));
    return true;
  }
  if (strncmp(key, "snow", 4) == 0) {
    applyRleStream(dst_rgb565, kStageRle_snow, sizeof(kStageRle_snow));
    if (strcmp(key, "snow_1") == 0) applyRleStream(dst_rgb565, kStageRle_snow_1, sizeof(kStageRle_snow_1));
    else if (strcmp(key, "snow_2") == 0) applyRleStream(dst_rgb565, kStageRle_snow_2, sizeof(kStageRle_snow_2));
    return true;
  }
  return true;
}

